// Bank energy index — record JAH-GPCS-POWERBANK-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"capacity_wh": 74, "watts": 65, "price_usd": 60};
var value = (m.capacity_wh*m.watts/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-POWERBANK-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-POWERBANK-000001|' + value.toFixed(2) + ' energy index');

